import React, { useEffect, useState } from "react";
import { Button, Modal, ModalHeader, ModalBody, Form, FormGroup, ModalFooter, Input, Label } from 'reactstrap';
import axios from 'axios';
import { useSnackbar } from 'notistack';

const UserList = () => {
    const { enqueueSnackbar } = useSnackbar();
    const [users, setUsers] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);
    const [userEdit, setUserEdit] = useState(null);
    const [isEdit, setIsEdit] = useState(false);
    const [modalDeleteOpen, setModalDeleteOpen] = useState(false);
    const [userDelete, setUserDelete] = useState(null);

    useEffect(() => {
        fetchUsers();
    }, []);

    const fetchUsers = async () => {
        try {
            const response = await axios.get('http://localhost/multimedios/Proyecto-grupal/API/users.php');
            setUsers(response.data);
        } catch (error) {
            console.error('Error al ejecutar', error);
        }
    };

    const handleUserSave = async () => {
        try {
            if (isEdit) {
                await axios.put('http://localhost/multimedios/Proyecto-grupal/API/users.php', userEdit);
                enqueueSnackbar('Usuario actualizado con éxito', { variant: 'success' });
            } else {
                await axios.post('http://localhost/multimedios/Proyecto-grupal/API/users.php', userEdit);
                enqueueSnackbar('Usuario creado con éxito', { variant: 'success' });
            }
            toggleModal();
            fetchUsers();
        } catch (error) {
            console.error('Error en el API', error);
            enqueueSnackbar('Error al guardar el usuario', { variant: 'error' });
        }
    };

    const handleUserDelete = async () => {
        try {
            await axios.delete('http://localhost/multimedios/Proyecto-grupal/API/users.php', {
                data: { idUser: userDelete.idUser }
            });
            enqueueSnackbar('Usuario eliminado con éxito', { variant: 'success' });
            toggleDeleteModal();
            fetchUsers();
        } catch (error) {
            console.error('Error en el API', error);
            enqueueSnackbar('Error al eliminar el usuario', { variant: 'error' });
        }
    };

    // El resto del código se mantiene sin cambios
    return (
        <div className="container">
            // El código JSX de tu componente sigue aquí
        </div>
    );
};

export default UserList;
